export function formatDate(dateStr: string | undefined | null): string {
  if (!dateStr) return '';
  try {
    const d = new Date(dateStr);
    return d.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
  } catch {
    return dateStr;
  }
}

export function daysAgo(dateStr: string | undefined | null): number {
  if (!dateStr) return 0;
  try {
    const d = new Date(dateStr);
    const now = new Date();
    const diff = now.getTime() - d.getTime();
    return Math.floor(diff / (1000 * 60 * 60 * 24));
  } catch {
    return 0;
  }
}

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { authenticatedGet, authenticatedPatch } from '@/utils/api';
import { COLORS } from '@/constants/Together';

interface CoupleTheme {
  themeColor: string;
  themeFont: string;
  partnerName: string;
  coupleId: string | null;
  anniversaryDate: string | null;
  inviteCode: string | null;
  hasCouple: boolean;
  refreshCouple: () => Promise<void>;
  updateTheme: (color: string, font: string) => Promise<void>;
}

const ThemeContext = createContext<CoupleTheme>({
  themeColor: COLORS.primary,
  themeFont: 'Nunito',
  partnerName: '',
  coupleId: null,
  anniversaryDate: null,
  inviteCode: null,
  hasCouple: false,
  refreshCouple: async () => {},
  updateTheme: async () => {},
});

export function ThemeProvider({ children }: { children: ReactNode }) {
  const [themeColor, setThemeColor] = useState(COLORS.primary);
  const [themeFont, setThemeFont] = useState('Nunito');
  const [partnerName, setPartnerName] = useState('');
  const [coupleId, setCoupleId] = useState<string | null>(null);
  const [anniversaryDate, setAnniversaryDate] = useState<string | null>(null);
  const [inviteCode, setInviteCode] = useState<string | null>(null);
  const [hasCouple, setHasCouple] = useState(false);

  const refreshCouple = async () => {
    try {
      const data = await authenticatedGet('/api/couples/me');
      if (data && data.id) {
        setHasCouple(true);
        setCoupleId(data.id);
        setAnniversaryDate(data.anniversary_date || null);
        setInviteCode(data.invite_code || null);
        if (data.theme_color) setThemeColor(data.theme_color);
        if (data.theme_font) setThemeFont(data.theme_font);
        if (data.partner_name) setPartnerName(data.partner_name);
      } else {
        setHasCouple(false);
      }
    } catch {
      setHasCouple(false);
    }
  };

  const updateTheme = async (color: string, font: string) => {
    setThemeColor(color);
    setThemeFont(font);
    try {
      await authenticatedPatch('/api/couples/me', { theme_color: color, theme_font: font });
    } catch (e) {
      console.error('[ThemeContext] updateTheme error:', e);
    }
  };

  useEffect(() => {
    refreshCouple();
  }, []);

  return (
    <ThemeContext.Provider value={{
      themeColor, themeFont, partnerName, coupleId,
      anniversaryDate, inviteCode, hasCouple,
      refreshCouple, updateTheme,
    }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useAppTheme() {
  return useContext(ThemeContext);
}

import React, { useRef, useCallback } from 'react';
import { Pressable, Animated, PressableProps } from 'react-native';

interface AnimatedPressableProps extends PressableProps {
  scaleValue?: number;
}

export function AnimatedPressable({
  onPress,
  style,
  children,
  disabled,
  scaleValue = 0.96,
  ...props
}: AnimatedPressableProps) {
  const scale = useRef(new Animated.Value(1)).current;

  const animateIn = useCallback(() => {
    Animated.spring(scale, {
      toValue: scaleValue,
      useNativeDriver: true,
      speed: 50,
      bounciness: 4,
    }).start();
  }, [scale, scaleValue]);

  const animateOut = useCallback(() => {
    Animated.spring(scale, {
      toValue: 1,
      useNativeDriver: true,
      speed: 50,
      bounciness: 4,
    }).start();
  }, [scale]);

  return (
    <Animated.View style={{ transform: [{ scale }] }}>
      <Pressable
        onPressIn={animateIn}
        onPressOut={animateOut}
        onPress={onPress}
        disabled={disabled}
        style={style}
        {...props}
      >
        {children}
      </Pressable>
    </Animated.View>
  );
}

