import React, { useState } from "react";
import {
  View,
  Text,
  TextInput,
  ScrollView,
  Image,
  ActivityIndicator,
  useWindowDimensions,
  Pressable,
} from "react-native";
import { useRouter } from "expo-router";
import * as ImagePicker from "expo-image-picker";
import { authenticatedPost } from "@/utils/api";
import { useAppTheme } from "@/contexts/ThemeContext";
import { COLORS, MEMORY_PROMPTS } from "@/constants/Together";
import { AnimatedPressable } from "@/components/AnimatedPressable";
import { Camera, Image as ImageIcon, Check } from "lucide-react-native";

export default function AddMemoryScreen() {
  const router = useRouter();
  const { themeColor } = useAppTheme();
  const { width } = useWindowDimensions();

  const [selectedPrompt, setSelectedPrompt] = useState("");
  const [imageUrl, setImageUrl] = useState("");
  const [caption, setCaption] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const maxWidth = Math.min(width, 600);

  const pickImage = async () => {
    console.log("[AddMemory] Pick image pressed");
    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ImagePicker.MediaTypeOptions.Images,
      allowsEditing: true,
      aspect: [4, 3],
      quality: 0.8,
    });
    if (!result.canceled && result.assets[0]) {
      setImageUrl(result.assets[0].uri);
    }
  };

  const handleSave = async () => {
    if (!selectedPrompt) {
      setError("Please select a prompt");
      return;
    }
    console.log("[AddMemory] Save pressed, prompt:", selectedPrompt);
    setLoading(true);
    setError("");
    try {
      await authenticatedPost("/api/memories", {
        prompt: selectedPrompt,
        image_url: imageUrl || undefined,
        caption: caption || undefined,
      });
      router.back();
    } catch (e: any) {
      console.error("[AddMemory] Save error:", e);
      setError(e?.message || "Failed to save memory");
    } finally {
      setLoading(false);
    }
  };

  return (
    <ScrollView
      style={{ flex: 1, backgroundColor: COLORS.background }}
      contentContainerStyle={{ padding: 20, paddingBottom: 60, maxWidth, alignSelf: "center", width: "100%" }}
      keyboardShouldPersistTaps="handled"
    >
      {/* Prompt Selection */}
      <Text style={{ fontSize: 18, fontWeight: "800", color: COLORS.text, marginBottom: 12 }}>
        Choose a Prompt
      </Text>
      <View style={{ flexDirection: "row", flexWrap: "wrap", gap: 8, marginBottom: 24 }}>
        {MEMORY_PROMPTS.map((prompt) => {
          const isSelected = selectedPrompt === prompt;
          return (
            <AnimatedPressable
              key={prompt}
              onPress={() => setSelectedPrompt(prompt)}
              style={{
                paddingHorizontal: 14,
                paddingVertical: 8,
                borderRadius: 20,
                backgroundColor: isSelected ? themeColor : COLORS.surface,
                borderWidth: 1.5,
                borderColor: isSelected ? themeColor : COLORS.border,
                flexDirection: "row",
                alignItems: "center",
                gap: 6,
              }}
            >
              {isSelected && <Check size={12} color="#fff" />}
              <Text style={{
                fontSize: 13,
                fontWeight: "600",
                color: isSelected ? "#fff" : COLORS.textSecondary,
              }}>
                {prompt}
              </Text>
            </AnimatedPressable>
          );
        })}
      </View>

      {/* Image Picker */}
      <Text style={{ fontSize: 18, fontWeight: "800", color: COLORS.text, marginBottom: 12 }}>
        Add a Photo
      </Text>
      <AnimatedPressable
        onPress={pickImage}
        style={{
          backgroundColor: COLORS.surface,
          borderRadius: 16,
          borderWidth: 2,
          borderColor: COLORS.border,
          borderStyle: "dashed",
          height: 180,
          alignItems: "center",
          justifyContent: "center",
          marginBottom: 12,
          overflow: "hidden",
        }}
      >
        {imageUrl ? (
          <Image source={{ uri: imageUrl }} style={{ width: "100%", height: "100%" }} resizeMode="cover" />
        ) : (
          <View style={{ alignItems: "center", gap: 8 }}>
            <Camera size={32} color={COLORS.textMuted} />
            <Text style={{ fontSize: 14, color: COLORS.textSecondary, fontWeight: "600" }}>
              Tap to pick a photo
            </Text>
          </View>
        )}
      </AnimatedPressable>

      {/* URL Input */}
      <Text style={{ fontSize: 13, color: COLORS.textSecondary, marginBottom: 8, fontWeight: "600" }}>
        Or paste an image URL
      </Text>
      <TextInput
        placeholder="https://..."
        placeholderTextColor={COLORS.textMuted}
        value={imageUrl}
        onChangeText={setImageUrl}
        autoCapitalize="none"
        keyboardType="url"
        style={{
          backgroundColor: COLORS.surface,
          borderRadius: 12,
          borderWidth: 1.5,
          borderColor: COLORS.border,
          paddingHorizontal: 14,
          paddingVertical: 12,
          fontSize: 14,
          color: COLORS.text,
          marginBottom: 24,
        }}
      />

      {/* Caption */}
      <Text style={{ fontSize: 18, fontWeight: "800", color: COLORS.text, marginBottom: 12 }}>
        Caption
      </Text>
      <TextInput
        placeholder="Write something about this moment... 💕"
        placeholderTextColor={COLORS.textMuted}
        value={caption}
        onChangeText={setCaption}
        multiline
        numberOfLines={4}
        style={{
          backgroundColor: COLORS.surface,
          borderRadius: 14,
          borderWidth: 1.5,
          borderColor: COLORS.border,
          paddingHorizontal: 16,
          paddingVertical: 14,
          fontSize: 15,
          color: COLORS.text,
          minHeight: 100,
          textAlignVertical: "top",
          marginBottom: 24,
        }}
      />

      {error ? (
        <Text style={{ color: COLORS.error, fontSize: 14, textAlign: "center", marginBottom: 12 }}>{error}</Text>
      ) : null}

      <AnimatedPressable
        onPress={handleSave}
        disabled={loading}
        style={{
          backgroundColor: themeColor,
          borderRadius: 16,
          paddingVertical: 14,
          alignItems: "center",
          boxShadow: `0 4px 16px ${themeColor}40`,
        }}
      >
        {loading
          ? <ActivityIndicator color="#fff" />
          : <Text style={{ color: "#fff", fontWeight: "700", fontSize: 16 }}>Save Memory 💕</Text>
        }
      </AnimatedPressable>
    </ScrollView>
  );
}

import React, { useState, useEffect } from "react";
import {
  View,
  Text,
  Image,
  ScrollView,
  ActivityIndicator,
  Modal,
  useWindowDimensions,
} from "react-native";
import { useRouter, useLocalSearchParams } from "expo-router";
import { authenticatedGet, authenticatedDelete } from "@/utils/api";
import { useAppTheme } from "@/contexts/ThemeContext";
import { COLORS, formatDate } from "@/constants/Together";
import { AnimatedPressable } from "@/components/AnimatedPressable";
import { Trash2 } from "lucide-react-native";

interface Memory {
  id: string;
  prompt: string;
  image_url?: string;
  caption?: string;
  created_at: string;
}

export default function MemoryDetailScreen() {
  const router = useRouter();
  const { id } = useLocalSearchParams<{ id: string }>();
  const { themeColor } = useAppTheme();
  const { width } = useWindowDimensions();

  const [memory, setMemory] = useState<Memory | null>(null);
  const [loading, setLoading] = useState(true);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [deleting, setDeleting] = useState(false);

  const imageSource = memory?.image_url ? { uri: memory.image_url } : null;
  const dateText = memory ? formatDate(memory.created_at) : "";

  useEffect(() => {
    const load = async () => {
      try {
        const data = await authenticatedGet<Memory>(`/api/memories/${id}`);
        setMemory(data);
      } catch (e) {
        console.error("[MemoryDetail] load error:", e);
      } finally {
        setLoading(false);
      }
    };
    if (id) load();
  }, [id]);

  const handleDelete = async () => {
    console.log("[MemoryDetail] Delete confirmed for:", id);
    setDeleting(true);
    try {
      await authenticatedDelete(`/api/memories/${id}`);
      router.back();
    } catch (e) {
      console.error("[MemoryDetail] Delete error:", e);
      setDeleting(false);
      setShowDeleteModal(false);
    }
  };

  if (loading) {
    return (
      <View style={{ flex: 1, justifyContent: "center", alignItems: "center", backgroundColor: COLORS.background }}>
        <ActivityIndicator color={themeColor} size="large" />
      </View>
    );
  }

  if (!memory) {
    return (
      <View style={{ flex: 1, justifyContent: "center", alignItems: "center", backgroundColor: COLORS.background }}>
        <Text style={{ fontSize: 16, color: COLORS.textSecondary }}>Memory not found</Text>
      </View>
    );
  }

  return (
    <View style={{ flex: 1, backgroundColor: "#000" }}>
      <ScrollView contentContainerStyle={{ paddingBottom: 40 }}>
        {imageSource ? (
          <Image
            source={imageSource}
            style={{ width, height: width * 0.85 }}
            resizeMode="cover"
          />
        ) : (
          <View style={{
            width,
            height: width * 0.85,
            backgroundColor: COLORS.surfaceAlt,
            alignItems: "center",
            justifyContent: "center",
          }}>
            <Text style={{ fontSize: 60 }}>📸</Text>
          </View>
        )}

        <View style={{ backgroundColor: COLORS.background, padding: 24 }}>
          <View style={{
            backgroundColor: `${themeColor}20`,
            borderRadius: 10,
            paddingHorizontal: 12,
            paddingVertical: 6,
            alignSelf: "flex-start",
            marginBottom: 12,
          }}>
            <Text style={{ fontSize: 13, fontWeight: "700", color: themeColor }}>
              {memory.prompt}
            </Text>
          </View>

          {memory.caption ? (
            <Text style={{ fontSize: 16, color: COLORS.text, lineHeight: 24, marginBottom: 12 }} selectable>
              {memory.caption}
            </Text>
          ) : null}

          <Text style={{ fontSize: 13, color: COLORS.textMuted }}>{dateText}</Text>

          <AnimatedPressable
            onPress={() => setShowDeleteModal(true)}
            style={{
              marginTop: 24,
              flexDirection: "row",
              alignItems: "center",
              justifyContent: "center",
              gap: 8,
              backgroundColor: COLORS.surface,
              borderRadius: 14,
              paddingVertical: 13,
              borderWidth: 1.5,
              borderColor: COLORS.error + "40",
            }}
          >
            <Trash2 size={18} color={COLORS.error} />
            <Text style={{ color: COLORS.error, fontWeight: "700", fontSize: 15 }}>Delete Memory</Text>
          </AnimatedPressable>
        </View>
      </ScrollView>

      <Modal visible={showDeleteModal} transparent animationType="fade">
        <View style={{ flex: 1, backgroundColor: "rgba(0,0,0,0.5)", justifyContent: "center", alignItems: "center", padding: 24 }}>
          <View style={{ backgroundColor: COLORS.surface, borderRadius: 24, padding: 28, width: "100%", maxWidth: 360 }}>
            <Text style={{ fontSize: 20, fontWeight: "800", color: COLORS.text, textAlign: "center", marginBottom: 8 }}>
              Delete Memory?
            </Text>
            <Text style={{ fontSize: 15, color: COLORS.textSecondary, textAlign: "center", marginBottom: 24, lineHeight: 22 }}>
              This memory will be permanently deleted. This cannot be undone.
            </Text>
            <View style={{ flexDirection: "row", gap: 12 }}>
              <AnimatedPressable
                onPress={() => setShowDeleteModal(false)}
                style={{ flex: 1, backgroundColor: COLORS.surfaceAlt, borderRadius: 14, paddingVertical: 13, alignItems: "center" }}
              >
                <Text style={{ fontWeight: "700", color: COLORS.text }}>Cancel</Text>
              </AnimatedPressable>
              <AnimatedPressable
                onPress={handleDelete}
                disabled={deleting}
                style={{ flex: 1, backgroundColor: COLORS.error, borderRadius: 14, paddingVertical: 13, alignItems: "center" }}
              >
                {deleting
                  ? <ActivityIndicator color="#fff" size="small" />
                  : <Text style={{ fontWeight: "700", color: "#fff" }}>Delete</Text>
                }
              </AnimatedPressable>
            </View>
          </View>
        </View>
      </Modal>
    </View>
  );
}

import React, { useState, useCallback } from "react";
import {
  View,
  Text,
  ScrollView,
  ActivityIndicator,
  useWindowDimensions,
  RefreshControl,
} from "react-native";
import { useRouter, useFocusEffect } from "expo-router";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { authenticatedGet, authenticatedDelete } from "@/utils/api";
import { useAppTheme } from "@/contexts/ThemeContext";
import { COLORS, MOODS, formatDate } from "@/constants/Together";
import { AnimatedPressable } from "@/components/AnimatedPressable";
import { Plus, Lock, Trash2, Heart } from "lucide-react-native";
import Modal from "react-native";

interface Mood {
  id: string;
  mood: string;
  note?: string;
  created_at: string;
}

interface Vent {
  id: string;
  content: string;
