                    </View>
                  );
                })}
              </View>
            )}
          </View>

          {/* AI Suggestions */}
          <View style={{ marginBottom: 24 }}>
            <Text style={{ fontSize: 18, fontWeight: "800", color: COLORS.text, marginBottom: 12 }}>
              ✨ AI Suggestions
            </Text>

            <AnimatedPressable
              onPress={handleGetSuggestions}
              disabled={aiLoading}
              style={{
                backgroundColor: COLORS.accent,
                borderRadius: 16,
                paddingVertical: 14,
                alignItems: "center",
                flexDirection: "row",
                justifyContent: "center",
                gap: 8,
                marginBottom: 16,
                boxShadow: "0 4px 16px rgba(167,139,250,0.4)",
              }}
            >
              {aiLoading ? (
                <ActivityIndicator color="#fff" size="small" />
              ) : (
                <>
                  <Sparkles size={18} color="#fff" />
                  <Text style={{ color: "#fff", fontWeight: "700", fontSize: 15 }}>
                    Get AI Suggestions ✨
                  </Text>
                </>
              )}
            </AnimatedPressable>

            {suggestions.length > 0 && (
              <View style={{ gap: 12 }}>
                {suggestions.map((suggestion, index) => (
                  <View
                    key={index}
                    style={{
                      backgroundColor: "#fff",
                      borderRadius: 16,
                      padding: 16,
                      borderLeftWidth: 4,
                      borderLeftColor: COLORS.accent,
                      boxShadow: "0 2px 8px rgba(167,139,250,0.1)",
                    }}
                  >
                    <Text style={{ fontSize: 15, fontWeight: "700", color: COLORS.text, marginBottom: 6 }}>
                      {suggestion.title}
                    </Text>
                    <Text style={{ fontSize: 13, color: COLORS.textSecondary, lineHeight: 18 }}>
                      {suggestion.description}
                    </Text>
                  </View>
                ))}
              </View>
            )}
          </View>
        </ScrollView>
      )}
    </View>
  );
}

import React, { useState, useRef } from "react";
import {
  View,
  Text,
  TextInput,
  ScrollView,
  ActivityIndicator,
  Animated,
  Pressable,
  useWindowDimensions,
} from "react-native";
import { useRouter } from "expo-router";
import { authenticatedPost } from "@/utils/api";
import { COLORS } from "@/constants/Together";
import { AnimatedPressable } from "@/components/AnimatedPressable";
import { Star } from "lucide-react-native";

export default function LogSatisfactionScreen() {
  const router = useRouter();
  const { width } = useWindowDimensions();

  const [rating, setRating] = useState(0);
  const [note, setNote] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const maxWidth = Math.min(width, 600);

  const starLabels = ["", "Not great", "Okay", "Good", "Great", "Amazing! 💜"];

  const handleSave = async () => {
    if (rating === 0) {
      setError("Please select a rating");
      return;
    }
    console.log("[LogSatisfaction] Save pressed, rating:", rating);
    setLoading(true);
    setError("");
    try {
      await authenticatedPost("/api/intimacy/logs", {
        rating,
        note: note.trim() || undefined,
      });
      router.back();
    } catch (e: any) {
      console.error("[LogSatisfaction] Save error:", e);
      setError(e?.message || "Failed to save log");
    } finally {
      setLoading(false);
    }
  };

  return (
    <ScrollView
      style={{ flex: 1, backgroundColor: "#F5F0FF" }}
      contentContainerStyle={{ padding: 24, paddingBottom: 60, maxWidth, alignSelf: "center", width: "100%" }}
      keyboardShouldPersistTaps="handled"
    >
      <Text style={{ fontSize: 22, fontWeight: "900", color: COLORS.text, marginBottom: 8 }}>
        Log Satisfaction 💜
      </Text>
      <Text style={{ fontSize: 15, color: COLORS.textSecondary, marginBottom: 32, lineHeight: 22 }}>
        How was your intimate connection today?
      </Text>

      {/* Star Rating */}
      <View style={{ alignItems: "center", marginBottom: 32 }}>
        <View style={{ flexDirection: "row", gap: 12, marginBottom: 12 }}>
          {[1, 2, 3, 4, 5].map((star) => (
            <AnimatedPressable
              key={star}
              onPress={() => {
                console.log("[LogSatisfaction] Star selected:", star);
                setRating(star);
              }}
              scaleValue={0.85}
              style={{ padding: 4 }}
            >
              <Star
                size={48}
                color={star <= rating ? "#FBBF24" : COLORS.border}
                fill={star <= rating ? "#FBBF24" : "transparent"}
              />
            </AnimatedPressable>
          ))}
        </View>
        {rating > 0 && (
          <Text style={{ fontSize: 16, fontWeight: "700", color: COLORS.accent }}>
            {starLabels[rating]}
          </Text>
        )}
      </View>

      {/* Note */}
      <Text style={{ fontSize: 16, fontWeight: "700", color: COLORS.text, marginBottom: 10 }}>
        Add a note (optional)
      </Text>
      <TextInput
        placeholder="Any thoughts or feelings to share... 💜"
        placeholderTextColor={COLORS.textMuted}
        value={note}
        onChangeText={setNote}
        multiline
        numberOfLines={4}
        style={{
          backgroundColor: "#fff",
          borderRadius: 14,
          borderWidth: 1.5,
          borderColor: `${COLORS.accent}30`,
          paddingHorizontal: 16,
          paddingVertical: 14,
          fontSize: 15,
          color: COLORS.text,
          minHeight: 100,
          textAlignVertical: "top",
          marginBottom: 24,
        }}
      />

      {error ? (
        <Text style={{ color: COLORS.error, fontSize: 14, textAlign: "center", marginBottom: 12 }}>{error}</Text>
      ) : null}

      <AnimatedPressable
        onPress={handleSave}
        disabled={loading}
        style={{
          backgroundColor: COLORS.accent,
          borderRadius: 16,
          paddingVertical: 14,
          alignItems: "center",
          boxShadow: "0 4px 16px rgba(167,139,250,0.4)",
        }}
      >
        {loading
          ? <ActivityIndicator color="#fff" />
          : <Text style={{ color: "#fff", fontWeight: "700", fontSize: 16 }}>Save Log 💜</Text>
        }
      </AnimatedPressable>
    </ScrollView>
  );
}

import React, { useState } from "react";
import {
  View,
  Text,
  TextInput,
  ScrollView,
  Switch,
  ActivityIndicator,
  useWindowDimensions,
} from "react-native";
import { useRouter } from "expo-router";
import { authenticatedPost } from "@/utils/api";
import { COLORS } from "@/constants/Together";
import { AnimatedPressable } from "@/components/AnimatedPressable";
import { Lock } from "lucide-react-native";

export default function AddFantasyScreen() {
  const router = useRouter();
  const { width } = useWindowDimensions();

  const [content, setContent] = useState("");
  const [isAnonymous, setIsAnonymous] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const maxWidth = Math.min(width, 600);

  const handleSave = async () => {
    if (!content.trim()) {
      setError("Please write something first");
      return;
    }
    console.log("[AddFantasy] Save pressed, anonymous:", isAnonymous);
    setLoading(true);
    setError("");
    try {
      await authenticatedPost("/api/intimacy/fantasies", {
        content: content.trim(),
        is_anonymous: isAnonymous,
      });
      router.back();
    } catch (e: any) {
      console.error("[AddFantasy] Save error:", e);
      setError(e?.message || "Failed to share fantasy");
    } finally {
      setLoading(false);
    }
  };

  return (
    <ScrollView
      style={{ flex: 1, backgroundColor: "#F5F0FF" }}
      contentContainerStyle={{ padding: 24, paddingBottom: 60, maxWidth, alignSelf: "center", width: "100%" }}
      keyboardShouldPersistTaps="handled"
    >
      <Text style={{ fontSize: 22, fontWeight: "900", color: COLORS.text, marginBottom: 8 }}>
        Share a Fantasy 💭
      </Text>
      <Text style={{ fontSize: 15, color: COLORS.textSecondary, marginBottom: 24, lineHeight: 22 }}>
        This is a safe, private space to share your desires with your partner. 💜
      </Text>

      <TextInput
        placeholder="Share what's on your mind... 💜"
        placeholderTextColor={COLORS.textMuted}
        value={content}
        onChangeText={setContent}
        multiline
        numberOfLines={8}
        style={{
          backgroundColor: "#fff",
          borderRadius: 16,
          borderWidth: 1.5,
          borderColor: `${COLORS.accent}30`,
          paddingHorizontal: 16,
          paddingVertical: 16,
          fontSize: 16,
          color: COLORS.text,
          minHeight: 200,
          textAlignVertical: "top",
          lineHeight: 24,
          marginBottom: 20,
        }}
        autoFocus
      />

      {/* Anonymous Toggle */}
      <View style={{
        backgroundColor: "#fff",
        borderRadius: 16,
        padding: 16,
        flexDirection: "row",
        alignItems: "center",
        justifyContent: "space-between",
        marginBottom: 24,
        boxShadow: "0 2px 8px rgba(167,139,250,0.1)",
      }}>
        <View style={{ flexDirection: "row", alignItems: "center", gap: 10, flex: 1 }}>
          <Lock size={18} color={isAnonymous ? COLORS.accent : COLORS.textMuted} />
          <View style={{ flex: 1 }}>
            <Text style={{ fontSize: 15, fontWeight: "700", color: COLORS.text }}>Share anonymously</Text>
            <Text style={{ fontSize: 12, color: COLORS.textSecondary, marginTop: 2 }}>
              Your name won't be shown
            </Text>
          </View>
        </View>
        <Switch
          value={isAnonymous}
          onValueChange={(val) => {
            console.log("[AddFantasy] Anonymous toggle:", val);
            setIsAnonymous(val);
          }}
          trackColor={{ false: COLORS.border, true: COLORS.accent }}
          thumbColor="#fff"
        />
      </View>

      {error ? (
        <Text style={{ color: COLORS.error, fontSize: 14, textAlign: "center", marginBottom: 12 }}>{error}</Text>
      ) : null}

      <AnimatedPressable
        onPress={handleSave}
        disabled={loading}
        style={{
          backgroundColor: COLORS.accent,
          borderRadius: 16,
          paddingVertical: 14,
          alignItems: "center",
          boxShadow: "0 4px 16px rgba(167,139,250,0.4)",
        }}
      >
        {loading
          ? <ActivityIndicator color="#fff" />
          : <Text style={{ color: "#fff", fontWeight: "700", fontSize: 16 }}>Share 💜</Text>
        }
      </AnimatedPressable>
    </ScrollView>
  );
}

